package com.digiaudit.grcpc.modules.masterdata.coverage.controlcontrolobjective.api;

import com.digiaudit.grcpc.modules.masterdata.coverage.controlcontrolobjective.api.dto.CentralControlControlObjectiveCoverageOptionsResponse; import com.digiaudit.grcpc.modules.masterdata.coverage.controlcontrolobjective.api.dto.CentralSubprocessControlControlObjectiveCoverageResponse; import com.digiaudit.grcpc.modules.masterdata.coverage.controlcontrolobjective.application.CentralSubprocessControlControlObjectiveCoverageQueryService; import com.digiaudit.grcpc.modules.masterdata.shared.domain.MasterDataLifecycleStatus; import java.util.List; import java.util.UUID; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/master-data/central")
public class CentralControlControlObjectiveCoverageQueryController {
  private final CentralSubprocessControlControlObjectiveCoverageQueryService queries; public CentralControlControlObjectiveCoverageQueryController(CentralSubprocessControlControlObjectiveCoverageQueryService queries){this.queries=queries;}
  @GetMapping("/subprocesses/{subprocessId}/control-control-objective-coverages") @PreAuthorize("@masterDataAuthorization.canView('PROCESS') and @masterDataAuthorization.canView('CONTROL')") public List<CentralSubprocessControlControlObjectiveCoverageResponse> list(@PathVariable UUID subprocessId,@RequestParam(required=false) MasterDataLifecycleStatus status,@RequestParam(required=false) String search){return queries.listForSubprocess(subprocessId,status,search);}
  @GetMapping("/subprocesses/{subprocessId}/control-control-objective-coverages/deleted") @PreAuthorize("@masterDataAuthorization.canView('PROCESS') and @masterDataAuthorization.canView('CONTROL')") public List<CentralSubprocessControlControlObjectiveCoverageResponse> deleted(@PathVariable UUID subprocessId,@RequestParam(required=false) String search){return queries.deleted(subprocessId,search);}
  @GetMapping("/subprocesses/{subprocessId}/control-control-objective-coverages/options") @PreAuthorize("@masterDataAuthorization.canView('PROCESS') and @masterDataAuthorization.canView('CONTROL')") public CentralControlControlObjectiveCoverageOptionsResponse options(@PathVariable UUID subprocessId){return queries.options(subprocessId);}
  @GetMapping("/subprocesses/{subprocessId}/control-control-objective-coverages/{coverageId}") @PreAuthorize("@masterDataAuthorization.canView('PROCESS') and @masterDataAuthorization.canView('CONTROL')") public CentralSubprocessControlControlObjectiveCoverageResponse detail(@PathVariable UUID subprocessId,@PathVariable UUID coverageId){return queries.detail(subprocessId,coverageId);}
  @GetMapping("/controls/{controlId}/control-objective-coverages") @PreAuthorize("@masterDataAuthorization.canView('PROCESS') and @masterDataAuthorization.canView('CONTROL')") public List<CentralSubprocessControlControlObjectiveCoverageResponse> forControl(@PathVariable UUID controlId,@RequestParam(required=false) String search){return queries.listForControl(controlId,search);}
  @GetMapping("/control-objectives/{controlObjectiveId}/control-coverages") @PreAuthorize("@masterDataAuthorization.canView('PROCESS') and @masterDataAuthorization.canView('CONTROL')") public List<CentralSubprocessControlControlObjectiveCoverageResponse> forObjective(@PathVariable UUID controlObjectiveId,@RequestParam(required=false) String search){return queries.listForControlObjective(controlObjectiveId,search);}
}
